// Intended function: route large vehicles through explicit compatible lanes and prevent deterministic node conflicts through leases.
#include "world/VehiclePathing.hpp"
#include <algorithm>
#include <limits>
#include <queue>
namespace elysium{void VehiclePathing::upsertNode(VehicleLaneNode n){nodes_[n.nodeId]=n;}void VehiclePathing::setEdges(std::uint64_t n,std::vector<VehicleLaneEdge>e){std::sort(e.begin(),e.end(),[](auto&a,auto&b){return a.toNode<b.toNode;});edges_[n]=std::move(e);}VehicleRoute VehiclePathing::route(std::uint64_t s,std::uint64_t g,float w,float slope)const{VehicleRoute o;if(!nodes_.contains(s)||!nodes_.contains(g))return o;struct Q{float d;std::uint64_t n;};struct C{bool operator()(Q a,Q b)const{return a.d>b.d||(a.d==b.d&&a.n>b.n);}};std::priority_queue<Q,std::vector<Q>,C>q;std::unordered_map<std::uint64_t,float>d;std::unordered_map<std::uint64_t,std::uint64_t>p;d[s]=0;q.push({0,s});while(!q.empty()){auto x=q.top();q.pop();if(x.d!=d[x.n])continue;if(x.n==g)break;auto ei=edges_.find(x.n);if(ei==edges_.end())continue;for(auto&e:ei->second){auto ni=nodes_.find(e.toNode);if(ni==nodes_.end()||ni->second.width<w||ni->second.maxSlope<slope)continue;auto c=x.d+e.distance*(1+e.hazard);if(!d.contains(e.toNode)||c<d[e.toNode]){d[e.toNode]=c;p[e.toNode]=x.n;q.push({c,e.toNode});}}}if(!d.contains(g))return o;o.found=true;o.distance=d[g];for(auto c=g;;c=p[c]){o.nodes.push_back(c);if(c==s)break;}std::reverse(o.nodes.begin(),o.nodes.end());float t=0;for(auto n:o.nodes)t+=1/std::max(.1f,nodes_.at(n).speedLimit);o.estimatedSeconds=o.distance*t/std::max<std::size_t>(1,o.nodes.size());return o;}bool VehiclePathing::reserveNode(std::uint64_t n,std::uint64_t v,std::uint64_t u){auto i=reservations_.find(n);if(i!=reservations_.end()&&i->second.vehicle!=v)return false;reservations_[n]={v,u};return true;}void VehiclePathing::expire(std::uint64_t t){for(auto i=reservations_.begin();i!=reservations_.end();)if(i->second.until<=t)i=reservations_.erase(i);else++i;}}
